{
  "requirement_id": "REQ-007",
  "summary": "專案成員身份驗證與任務讀取權限控制",
  "acceptance_criteria": [
    "專案、任務列表與任務詳情（GET /api/tasks/{tid}）僅限該專案成員讀取",
    "非專案成員存取時回傳 403 錯誤",
    "請求的資源不存在時回傳 404 錯誤"
  ]
}

