{
  "requirement_id": "REQ-007",
  "cases": [
    {
      "id": "TC-1",
      "title": "Project member can read task details",
      "surface": "api",
      "steps": [
        "POST /api/projects as alice to create a project",
        "POST /api/tasks/{pid} as alice to create a task",
        "GET /api/tasks/{tid} as alice"
      ],
      "expected": "專案、任務列表與任務詳情（GET /api/tasks/{tid}）僅限該專案成員讀取"
    },
    {
      "id": "TC-2",
      "title": "Non-project member receives 403 when reading task details",
      "surface": "api",
      "steps": [
        "POST /api/projects as alice to create a project",
        "POST /api/tasks/{pid} as alice to create a task",
        "GET /api/tasks/{tid} with header X-User: bob where bob is not a member"
      ],
      "expected": "非專案成員存取時回傳 403 錯誤"
    },
    {
      "id": "TC-3",
      "title": "Requesting a non-existent task returns 404",
      "surface": "api",
      "steps": [
        "GET /api/tasks/99999 with header X-User: alice"
      ],
      "expected": "請求的資源不存在時回傳 404 錯誤"
    }
  ]
}

